mapper.select:
SELECT p.plan_id AS planId, p.greenhouse_id AS greenhouseId, p.member_id AS memberId, p.standard_id AS standardId, p.plan_name AS planName, p.plan_status AS planStatus, p.planned_start_date AS plannedStartDate, p.planned_end_date AS plannedEndDate, p.created_at AS createdAt, p.actual_start_date AS actualStartDate, p.actual_end_date AS actualEndDate, p.end_reason AS endReason, g.greenhouse_name AS greenhouseName, c.crop_id AS cropId,
       c.crop_name AS cropName, c.variety_name AS varietyName, s.growth_stage AS growthStage
FROM cultivation_plan p
JOIN greenhouse g ON g.greenhouse_id = p.greenhouse_id
JOIN crop_stage_standard s ON s.standard_id = p.standard_id
JOIN crop c ON c.crop_id = s.crop_id
WHERE p.member_id = #{memberId}
AND p.greenhouse_id = #{greenhouseId}
AND c.crop_id = #{cropId}
AND p.plan_status = #{status}
ORDER BY p.created_at DESC, p.plan_id DESC

SELECT d.diary_id AS diaryId, d.plan_id AS planId, d.worked_at AS workedAt, d.created_at AS createdAt, d.growth_stage AS growthStage, d.updated_at AS updatedAt, d.stage_change_reason AS stageChangeReason, p.plan_name AS planName, g.greenhouse_name AS greenhouseName,
       c.crop_name AS cropName, c.variety_name AS varietyName,
       (SELECT COUNT(*) FROM cultivation_diary_task t WHERE t.diary_id = d.diary_id) AS taskCount
FROM cultivation_diary d
JOIN cultivation_plan p ON p.plan_id = d.plan_id
JOIN greenhouse g ON g.greenhouse_id = p.greenhouse_id
JOIN crop_stage_standard s ON s.standard_id = p.standard_id
JOIN crop c ON c.crop_id = s.crop_id
WHERE p.member_id = #{memberId}
AND d.plan_id = #{planId}
AND c.crop_name = #{cropName}
AND c.variety_name = #{varietyName}
AND p.greenhouse_id = #{greenhouseId}
AND d.worked_at >= #{from}
AND d.worked_at < #{to}
ORDER BY d.worked_at DESC, d.diary_id DESC
